			"Word.OMathFunctions": {"displayName":"OMathFunctions","members":[{"name":"Add","kind":"method","returns":"Word.OMathFunction","signature":"Add(Range As Range, Type As WdOMathFunctionType, [NumArgs As Variant], [NumCols As Variant]) As OMathFunction","doc":{"summary":"Inserts a new structure, such as a fraction, into an equation at the specified position and returns an OMathFunction object that represents the structure.","params":[{"name":"Range","text":"The place at which to insert an equation.","type":"Range"},{"name":"Type","text":"The type of equation to insert.","type":"WdOMathFunctionType"},{"name":"NumArgs","text":"The number of arguments in the equation.","type":"Variant"},{"name":"NumCols","text":"The number of columns in the equation.","type":"Variant"}],"source":"external"}},{"name":"Application","kind":"property","returns":"Word.Application","declaredType":"Application","access":"read-only","doc":{"summary":"Returns an Application object that represents the Microsoft Word application.","params":[],"source":"external"}},{"name":"Count","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Returns the number of items in the OMathFunctions collection. Read-only Long.","params":[],"source":"external"}},{"name":"Creator","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the add-in was created. Read-only Long.","params":[],"source":"external"}},{"name":"Item","kind":"method","returns":"Word.OMathFunction","signature":"Item(Index As Long) As OMathFunction","doc":{"summary":"Returns an OMathFunction object that represents the specified item in the collection.","params":[{"name":"Index","text":"Specifies the ordinal position of the object within the collection.","type":"Long"}],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Returns an Object that represents the parent object of the specified OMathFunctions object.","params":[],"source":"external"}}],"doc":{"summary":"Represents a collection of functions or structures that Microsoft Word supports, such as fractions, integrals, sums, and radicals.","params":[],"source":"external"}},
			"Word.OMathGroupChar": {"displayName":"OMathGroupChar","members":[{"name":"AlignTop","kind":"property","declaredType":"Boolean","access":"read/write","doc":{"summary":"Returns or sets a Boolean that represents whether the grouping character is aligned vertically with the surrounding text or whether the base text that is either above or below the grouping character is aligned vertically with the surrounding text. Read/write.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"Word.Application","declaredType":"Application","access":"read-only","doc":{"summary":"Returns an Application object that represents the Microsoft Word application.","params":[],"source":"external"}},{"name":"Char","kind":"property","declaredType":"Integer","access":"read/write","doc":{"summary":"Returns or sets an Integer that represents the character placed above or below text in a group character object. Read/write.","params":[],"source":"external"}},{"name":"CharTop","kind":"property","declaredType":"Boolean","access":"read/write","doc":{"summary":"Returns or sets a Boolean that represents whether the grouping character is placed above the base text of the group character object. False displays the group character under the base text. Read/write.","params":[],"source":"external"}},{"name":"Creator","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the add-in was created. Read-only Long.","params":[],"source":"external"}},{"name":"E","kind":"property","returns":"Word.OMath","declaredType":"OMath","access":"read-only","doc":{"summary":"Returns an OMath object that represents the base of the specified equation object. Read-only.","params":[],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Returns an Object that represents the parent object of the specified OMathGroupChar object.","params":[],"source":"external"}}],"doc":{"summary":"Represents a group character object, consisting of a character drawn above or below text, often with the purpose of visually grouping items.","remarks":"Generally, this character is a curly brace, bracket, or arrow but it can be any character.","params":[],"source":"external"}},
