			"Word.OMathMatCol": {"displayName":"OMathMatCol","members":[{"name":"Align","kind":"property","declaredType":"WdOMathHorizAlignType","access":"read/write","doc":{"summary":"Returns or sets a WdOMathHorizAlignType constant that represents the horizontal alignment for arguments in a matrix column. Read/write.","params":[],"source":"external"}},{"name":"Application","kind":"property","returns":"Word.Application","declaredType":"Application","access":"read-only","doc":{"summary":"Returns an Application object that represents the Microsoft Word application.","params":[],"source":"external"}},{"name":"Args","kind":"property","returns":"Word.OMathArgs","declaredType":"OMathArgs","access":"read-only","doc":{"summary":"Returns an OMathArgs object that represents the arguments in a matrix column. Read-only.","params":[],"source":"external"}},{"name":"ColIndex","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Returns a Long that represents the ordinal position of a column within the collection of columns in a matrix. Read-only.","params":[],"source":"external"}},{"name":"Creator","kind":"property","declaredType":"Long","access":"read-only","doc":{"summary":"Returns a 32-bit integer that indicates the application in which the add-in was created. Read-only Long.","params":[],"source":"external"}},{"name":"Delete","kind":"method","signature":"Delete()","doc":{"summary":"Deletes the specified matrix column.","params":[],"source":"external"}},{"name":"Parent","kind":"property","declaredType":"Object","access":"read-only","doc":{"summary":"Returns an Object that represents the parent object of the specified OMathMatCol object.","params":[],"source":"external"}}],"doc":{"summary":"Represents a matrix column. The OMathMatCol is a member of the OMathMatCols collection.","params":[],"source":"external"}},
